// The 500 most common Spanish verbs, bundled locally (no API), in rough order
// of frequency. The first 120 keep their original order, so daily progress
// (one new verb a day) carries over. Each verb has its meaning(s) and an example
// sentence with a literal English gloss; every conjugation is generated by
// ./conjugate.ts from the irregularity specs below.

import { conjugate, describe, type Conjugated, type Spec, type Tense } from './conjugate'

export interface SpanishVerb {
  rank: number // 1 = most common
  infinitive: string
  english: string // primary meaning(s); "/" separates accepted alternatives
  example: { es: string; en: string } // en = literal-ish English
  regular: boolean
  notes: string[] // what's irregular (or a spelling change), with an example form
  spec: Spec
}

