const cache = new Map<string, Conjugated>()

// All tenses for a verb (computed once, then cached).
export function conjugationOf(verb: SpanishVerb): Conjugated {
  let c = cache.get(verb.infinitive)
  if (!c) {
    c = conjugate(verb.infinitive, verb.spec, SPECS)
    cache.set(verb.infinitive, c)
  }
  return c
}

// Does this tense make sense for the verb (haber has no imperative, …)?
export const hasTense = (verb: SpanishVerb, tense: Tense) => !verb.spec.skip?.includes(tense)

export const VERBS: SpanishVerb[] = LIST.map(([infinitive, english, es, en], i) => {
  const spec = SPECS[infinitive] ?? {}
  const { regular, notes } = describe(infinitive, spec, SPECS, conjugate(infinitive, spec, SPECS))
  return { rank: i + 1, infinitive, english, example: { es, en }, regular, notes, spec }
})
